const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const antakya = ee.Geometry.Point(36.1632, 36.2066); // Approximate coordinates for Antakya
  const altinozu = ee.Geometry.Point(36.376, 36.083); // Approximate coordinates for Altınözü

  const start_date_period_start = '2023-02-15'; // A few days before Feb 21
  const start_date_period_end = '2023-02-28';   // End of Feb

  const end_date_period_start = '2023-04-20';   // A few days before April 30
  const end_date_period_end = '2023-04-30';     // End of April

  const scale = 500; // VNP46A1 native resolution is 500m

  // Function to mask poor quality pixels in VNP46A1
  function maskVNP46A1(image) {
    // Quality flags:
    // Bits 0-3: Mandatory_Quality_Flag
    //   0: Optimal
    //   1: Good
    //   2-15: Not optimal or bad data (e.g., cloudy, uncertain, filled)
    var mqf = image.select('Mandatory_Quality_Flag');
    // We want MQF 0 (optimal) or 1 (good)
    var goodQuality = mqf.lte(1);
    return image.updateMask(goodQuality);
  }

  // 2. Data Acquisition & Check
  const ntl_collection = ee.ImageCollection('NOAA/VIIRS/DNB/VNP46A1');

  const getPeriodMean = async (geometry, start_date, end_date, name) => {
    let collection = ntl_collection
      .filterBounds(geometry)
      .filterDate(start_date, end_date)
      .map(maskVNP46A1);

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No images found for ${name} between ${start_date} and ${end_date}.`);
      return { value: null, count: 0, size: 0 };
    }

    const meanImage = collection.select('DNB_BRDF_Nadir_Corrected_NTL').mean();

    // 3. Processing (Calculate pixel count to detect C2)
    const count = await meanImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
    }).get('DNB_BRDF_Nadir_Corrected_NTL').getInfo();

    if (count === 0) {
      console.log(`No valid pixels for ${name} after masking between ${start_date} and ${end_date}.`);
      return { value: null, count: 0, size: collectionSize };
    }

    // 4. Calculation
    const meanValue = await meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
    }).get('DNB_BRDF_Nadir_Corrected_NTL').getInfo();

    return { value: meanValue, count: count, size: collectionSize };
  };

  // Antakya
  const antakya_start_data = await getPeriodMean(antakya, start_date_period_start, start_date_period_end, 'Antakya start period');
  const antakya_end_data = await getPeriodMean(antakya, end_date_period_start, end_date_period_end, 'Antakya end period');

  // Altınözü
  const altinozu_start_data = await getPeriodMean(altinozu, start_date_period_start, start_date_period_end, 'Altınözü start period');
  const altinozu_end_data = await getPeriodMean(altinozu, end_date_period_start, end_date_period_end, 'Altınözü end period');

  // Check for C1 (Empty Collection)
  if (antakya_start_data.size === 0 || antakya_end_data.size === 0 ||
      altinozu_start_data.size === 0 || altinozu_end_data.size === 0) {
    console.log("C1: Empty Collection detected for one or more periods/locations.");
    console.log("Antakya Start Images:", antakya_start_data.size);
    console.log("Antakya End Images:", antakya_end_data.size);
    console.log("Altınözü Start Images:", altinozu_start_data.size);
    console.log("Altınözü End Images:", altinozu_end_data.size);
    console.log("C1");
    return;
  }

  // Check for C2 (No Valid Pixels)
  if (antakya_start_data.count === 0 || antakya_end_data.count === 0 ||
      altinozu_start_data.count === 0 || altinozu_end_data.count === 0) {
    console.log("C2: No Valid Pixels detected for one or more periods/locations after masking.");
    console.log("Antakya Start Pixels:", antakya_start_data.count);
    console.log("Antakya End Pixels:", antakya_end_data.count);
    console.log("Altınözü Start Pixels:", altinozu_start_data.count);
    console.log("Altınözü End Pixels:", altinozu_end_data.count);
    console.log("C2");
    return;
  }

  // Check for C3 (Calculation Failure - None/NaN)
  const allValues = [
    antakya_start_data.value, antakya_end_data.value,
    altinozu_start_data.value, altinozu_end_data.value
  ];
  if (allValues.some(v => v === null || isNaN(v))) {
    console.log("C3: Calculation Failure (None/NaN) detected.");
    console.log("Antakya Start NTL:", antakya_start_data.value);
    console.log("Antakya End NTL:", antakya_end_data.value);
    console.log("Altınözü Start NTL:", altinozu_start_data.value);
    console.log("Altınözü End NTL:", altinozu_end_data.value);
    console.log("C3");
    return;
  }

  // Calculate NTL change
  const antakya_change = antakya_end_data.value - antakya_start_data.value;
  const altinozu_change = altinozu_end_data.value - altinozu_start_data.value;

  // 5. Validation & Final Answer
  console.log(`Antakya:`);
  console.log(`  Start NTL (Images: ${antakya_start_data.size}, Pixels: ${antakya_start_data.count}): ${antakya_start_data.value.toFixed(2)}`);
  console.log(`  End NTL (Images: ${antakya_end_data.size}, Pixels: ${antakya_end_data.count}): ${antakya_end_data.value.toFixed(2)}`);
  console.log(`  Change: ${antakya_change.toFixed(2)}`);

  console.log(`Altınözü:`);
  console.log(`  Start NTL (Images: ${altinozu_start_data.size}, Pixels: ${altinozu_start_data.count}): ${altinozu_start_data.value.toFixed(2)}`);
  console.log(`  End NTL (Images: ${altinozu_end_data.size}, Pixels: ${altinozu_end_data.count}): ${altinozu_end_data.value.toFixed(2)}`);
  console.log(`  Change: ${altinozu_change.toFixed(2)}`);

  if (antakya_change > altinozu_change) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
